import json, glob, datetime

files = glob.glob('/home/agent/.gemini/tmp/workspace/tool-outputs/**/mcp_mcpb8e5e505_linear_list_issues*.txt', recursive=True)
all_issues = {}
for f in files:
    with open(f) as fp:
        data = json.load(fp)
        for issue in data.get('issues', []):
            if issue['team_id'] == 'team_ART':
                all_issues[issue['id']] = issue

# Get users
users_files = glob.glob('/home/agent/.gemini/tmp/workspace/tool-outputs/**/mcp_mcpb8e5e505_linear_show_data*.txt', recursive=True)
user_map = {}
for f in users_files:
    with open(f) as fp:
        data = json.load(fp)
        for u in data.get('users', []):
            user_map[u['id']] = u.get('name') or u.get('email')

closed_states = {'Done', 'Canceled', 'Duplicate'}
open_issues = [i for i in all_issues.values() if i['state_id'] not in closed_states]

ref_date = datetime.datetime(2026, 1, 27, 0, 0, 0, tzinfo=datetime.timezone.utc)
cutoff_date = datetime.datetime(2025, 1, 27, 0, 0, 0, tzinfo=datetime.timezone.utc)

stale_issues = []
active_issues = []

for issue in open_issues:
    # updated_at string parse
    up_str = issue['updated_at']
    up_dt = datetime.datetime.fromisoformat(up_str.replace('Z', '+00:00'))
    if up_dt < cutoff_date:
        stale_issues.append(issue)
    else:
        active_issues.append(issue)

print(f'Total Open Count: {len(open_issues)}')
print(f'Stale Count (not moved in last 12 months, < 2025-01-27): {len(stale_issues)}')
print(f'Active Count (moved in last 12 months, >= 2025-01-27): {len(active_issues)}')

print('\nSplit by owner (all open issues):')
owner_counts = {}
for issue in open_issues:
    aid = issue['assignee_id']
    name = user_map.get(aid, 'Unassigned' if aid is None else aid)
    owner_counts[name] = owner_counts.get(name, 0) + 1

for name, count in sorted(owner_counts.items(), key=lambda x: x[1], reverse=True):
    print(f'  {name}: {count}')

print('\nSplit by owner (stale issues only):')
stale_owner_counts = {}
for issue in stale_issues:
    aid = issue['assignee_id']
    name = user_map.get(aid, 'Unassigned' if aid is None else aid)
    stale_owner_counts[name] = stale_owner_counts.get(name, 0) + 1

for name, count in sorted(stale_owner_counts.items(), key=lambda x: x[1], reverse=True):
    print(f'  {name}: {count}')
"

